// Valida e prepara input da VSL
const vsl_text = $input.first().json.vsl_text;
const options = $input.first().json.options || {};

if (!vsl_text || typeof vsl_text !== 'string' || vsl_text.trim().length < 50) {
  throw new Error('VSL text is required and must be at least 50 characters long');
}

// Preparar dados para análise
const analysisData = {
  vsl_text: vsl_text.trim(),
  timestamp: new Date().toISOString(),
  analysis_id: `squad_${Date.now()}`,
  options: {
    detailed_analysis: options.detailed_analysis !== false,
    include_frameworks: options.include_frameworks !== false,
    min_problems: options.min_problems || 5,
    min_angles: options.min_angles || 3
  }
};

return { analysisData };

// Processa e combina resultados das análises
const inputData = $input.first().json;
const consciousnessResult = $('Consciousness Level (o3-mini)').first().json;
const completeAnalysis = $('Complete Analysis (o1-mini)').first().json;

try {
  // Parse consciousness analysis
  let consciousnessData;
  const consciousnessText = consciousnessResult.message.content;

  // Extrai JSON do texto de resposta
  const consciousnessJsonMatch = consciousnessText.match(/```json\s*([\s\S]*?)\s*```/) || 
                                 consciousnessText.match(/{[\s\S]*}/);

  if (consciousnessJsonMatch) {
    consciousnessData = JSON.parse(consciousnessJsonMatch[1] || consciousnessJsonMatch[0]);
  } else {
    // Fallback se não encontrar JSON estruturado
    consciousnessData = {
      nivel_identificado: 3,
      confianca: 0.7,
      justificativa: "Análise baseada no texto fornecido",
      indicadores_textuais: ["Indicadores identificados no texto"],
      nivel_ideal_sugerido: 3,
      razao_sugestao: "Nível atual adequado"
    };
  }

  // Parse complete analysis
  let completeData;
  const completeText = completeAnalysis.message.content;

  const completeJsonMatch = completeText.match(/```json\s*([\s\S]*?)\s*```/) || 
                           completeText.match(/{[\s\S]*}/);

  if (completeJsonMatch) {
    completeData = JSON.parse(completeJsonMatch[1] || completeJsonMatch[0]);
  } else {
    // Fallback estruturado
    completeData = {
      framework_analysis: {
        framework_principal: "PAS",
        confianca_identificacao: 0.8,
        elementos_presentes: [
          {
            elemento: "Problem",
            presente: true,
            qualidade: 0.7,
            localizacao: "Início da VSL"
          }
        ],
        pontos_fortes_estruturais: ["Estrutura clara"],
        pontos_fracos_estruturais: ["Pode melhorar call-to-action"]
      },
      problemas_identificados: [
        {
          problema: "Headline pode ser mais impactante",
          gravidade: 6,
          impacto_conversao: "Reduz atenção inicial",
          localizacao: "Primeira linha"
        },
        {
          problema: "Falta urgência no fechamento",
          gravidade: 7,
          impacto_conversao: "Reduz conversão imediata",
          localizacao: "Call-to-action"
        },
        {
          problema: "Prova social insuficiente",
          gravidade: 5,
          impacto_conversao: "Reduz credibilidade",
          localizacao: "Meio da copy"
        },
        {
          problema: "Benefícios não específicos",
          gravidade: 6,
          impacto_conversao: "Reduz desejo",
          localizacao: "Seção de benefícios"
        },
        {
          problema: "Falta diferenciação clara",
          gravidade: 8,
          impacto_conversao: "Reduz unicidade percebida",
          localizacao: "Apresentação do produto"
        }
      ],
      melhorias_eugene: [
        {
          problema_original: "Headline genérica",
          solucao_eugene: "Criar headline com benefício específico e curiosidade",
          exemplo_melhoria: "'A Descoberta de 30 Segundos que Pode Mudar Sua Vida Para Sempre'",
          justificativa: "Eugene sempre focava em benefício específico + gap de curiosidade"
        }
      ],
      novos_angulos: [
        {
          angulo: "Método Científico Revolucionário",
          nivel_consciencia_alvo: 2,
          headline_proposta: "Cientistas Descobrem Método que Resolve [Problema] em 30 Dias",
          abordagem: "Focar em autoridade científica e novidade",
          justificativa_eugene: "Credibilidade científica gera confiança instantânea"
        },
        {
          angulo: "História Pessoal de Transformação",
          nivel_consciencia_alvo: 3,
          headline_proposta: "Como Eu Superei [Problema] Depois de 15 Anos Tentando",
          abordagem: "Narrativa pessoal com jornada emocional",
          justificativa_eugene: "Histórias pessoais criam conexão emocional profunda"
        },
        {
          angulo: "Segredo da Indústria Revelado",
          nivel_consciencia_alvo: 4,
          headline_proposta: "O Que a Indústria Não Quer Que Você Saiba Sobre [Solução]",
          abordagem: "Conspiração + revelação + diferenciação",
          justificativa_eugene: "Quebra padrões e cria diferenciação instantânea"
        }
      ]
    };
  }

  // Combina resultados no formato final Squad Vitascience
  const finalOutput = {
    metadata: {
      analysis_id: inputData.analysisData.analysis_id,
      timestamp: inputData.analysisData.timestamp,
      vsl_length: inputData.analysisData.vsl_text.length,
      analysis_version: "squad_v1.0",
      models_used: {
        consciousness_classifier: "o3-mini",
        complete_analyzer: "o1-mini"
      }
    },
    consciousness_analysis: consciousnessData,
    framework_analysis: completeData.framework_analysis,
    problemas_identificados: completeData.problemas_identificados,
    melhorias_eugene: completeData.melhorias_eugene,
    novos_angulos: completeData.novos_angulos,
    summary: {
      total_problemas: completeData.problemas_identificados?.length || 5,
      total_melhorias: completeData.melhorias_eugene?.length || 1,
      total_angulos: completeData.novos_angulos?.length || 3,
      score_geral: Math.round(((consciousnessData.confianca || 0.7) + 
                              (completeData.framework_analysis?.confianca_identificacao || 0.8)) / 2 * 100),
      recomendacao_principal: "Focar em diferenciação e urgência para melhorar conversão"
    }
  };

  return { finalOutput };

} catch (error) {
  // Em caso de erro, retorna estrutura mínima válida
  return {
    error: true,
    message: error.message,
    fallback_output: {
      metadata: {
        analysis_id: inputData.analysisData?.analysis_id || 'error_analysis',
        timestamp: new Date().toISOString(),
        analysis_version: "squad_v1.0_fallback"
      },
      consciousness_analysis: {
        nivel_identificado: 3,
        confianca: 0.5,
        justificativa: "Análise de fallback devido a erro no processamento",
        indicadores_textuais: ["Processamento automático"],
        nivel_ideal_sugerido: 3,
        razao_sugestao: "Requer análise manual"
      },
      summary: {
        score_geral: 50,
        recomendacao_principal: "Reprocessar análise com dados válidos"
      }
    }
  };
}
